export function calculate(values: number[]) {
  let sum = 0;
  for (const value of values) {
    if (value > 0) sum += value;
    if (value > 5) sum += value;
    if (value > 10) sum += value;
    if (value > 15) sum += value;
    if (value > 20) sum += value;
  }
  return sum;
}

